#!/usr/bin/env bash
# file_issues.sh — file the Round-4 audit (CODE_REVIEW_2026-08-07.md) as GitHub issues + milestones.
#
# Generated 2026-08-07 from the audit's machine-verified findings JSON. Payload below is DATA —
# the driver computes nothing. 7 milestones, 43 issues, wave-then-severity order.
#
# USAGE (from the repo root on the Mac):
#   bash file_issues.sh --dry-run    # prints exactly what it would create, touches nothing
#   bash file_issues.sh              # files for real; writes/updates r4-issue-map.tsv
#
# IDEMPOTENT: re-running skips milestones that exist (by exact title) and any finding already
# recorded in r4-issue-map.tsv — safe to re-run after a partial failure.
# REQUIRES: gh (authenticated), python3. Do NOT commit this script or the map (untracked;
# park both in docs/archive/ when done).
set -euo pipefail
command -v gh >/dev/null || { echo "gh not found"; exit 1; }
command -v python3 >/dev/null || { echo "python3 not found"; exit 1; }

PAYLOAD="$(mktemp "${TMPDIR:-/tmp}/r4_payload.XXXXXX")"
trap 'rm -f "$PAYLOAD"' EXIT
cat > "$PAYLOAD" <<'R4_PAYLOAD_EOF_7f3a'
