import json, subprocess, sys, time, os

DRY = "--dry-run" in sys.argv
payload = json.load(open(sys.argv[1]))
REPO = payload["repo"]
MAP = "r4-issue-map.tsv"

def gh(args, inp=None):
    # NOTE: every WRITE call site is guarded by DRY checks before reaching here;
    # calls that arrive in dry-run mode are read-only (labels/milestones listings).
    r = subprocess.run(["gh"] + args, input=inp, capture_output=True, text=True)
    if r.returncode != 0:
        raise SystemExit(f"gh {' '.join(args[:4])}... failed:\n{r.stderr.strip()}")
    return r.stdout

def gh_json(args, inp=None):
    out = gh(args, inp)
    return json.loads(out) if out else None

# ---- 0. sanity ----
subprocess.run(["gh", "auth", "status"], check=True, capture_output=True)
print(f"Filing Round-4 audit into {REPO}" + (" [DRY RUN]" if DRY else ""))

# ---- 1. labels (create missing) ----
existing_labels = {l["name"] for l in gh_json(["api", f"repos/{REPO}/labels?per_page=100"])}
LABEL_COLORS = {"code-review": "5319e7", "bug": "d73a4a", "security": "b60205",
                "architecture": "1d76db", "testing": "0e8a16", "documentation": "0075ca",
                "data-integrity": "e11d21", "severity:high": "d93f0b", "severity:medium": "fbca04",
                "severity:low": "c2e0c6", "severity:nit": "ededed"}
for lab in payload["labels"]:
    if lab not in existing_labels:
        print(f"  creating label: {lab}")
        if not DRY:
            gh(["api", f"repos/{REPO}/labels", "-f", f"name={lab}",
                "-f", f"color={LABEL_COLORS.get(lab, 'cccccc')}"])

# ---- 2. milestones (create missing by exact title; MCP can't do this, gh api can) ----
existing_ms = gh_json(["api", f"repos/{REPO}/milestones?state=all&per_page=100"])
ms_number = {m["title"]: m["number"] for m in existing_ms}
for m in payload["milestones"]:
    if m["title"] in ms_number:
        print(f"  milestone exists (#{ms_number[m['title']]}): {m['title']}")
        continue
    print(f"  creating milestone: {m['title']}")
    if DRY:
        ms_number[m["title"]] = -1
    else:
        created = gh_json(["api", f"repos/{REPO}/milestones", "--input", "-"],
                          inp=json.dumps({"title": m["title"], "description": m["description"]}))
        ms_number[m["title"]] = created["number"]
        time.sleep(0.5)

# ---- 3. issues (idempotent via the map file; wave-then-severity order) ----
done = set()
if os.path.exists(MAP):
    for line in open(MAP):
        if line.strip():
            done.add(line.split("\t")[0])
    print(f"  map file found: {len(done)} issue(s) already filed, skipping those")

created_n = 0
mapf = None if DRY else open(MAP, "a")
for iss in payload["issues"]:
    fid = iss["finding_id"]
    if fid in done:
        continue
    req = {"title": iss["title"], "body": iss["body"], "labels": iss["labels"],
           "milestone": ms_number[iss["milestone_title"]]}
    if DRY:
        print(f"  [dry-run] would create: {iss['title'][:100]}  (milestone '{iss['milestone_title']}', labels {iss['labels']})")
        created_n += 1
        continue
    created = gh_json(["api", f"repos/{REPO}/issues", "--input", "-"], inp=json.dumps(req))
    num = created["number"]
    mapf.write(f"{fid}\t{num}\t{iss['title']}\n")
    mapf.flush()
    created_n += 1
    print(f"  #{num}  {fid}  {iss['title'][:90]}")
    time.sleep(1.0)  # be polite to the API
if mapf:
    mapf.close()

print(f"\nDone: {created_n} issue(s) {'would be ' if DRY else ''}created, {len(done)} skipped as already filed.")
print(f"Map: {MAP}  — ALWAYS grep this for the number before writing any 'Closes #NNN'.")
if not DRY:
    total = len(done) + created_n
    exp = payload["expected_issue_count"]
    print(f"Filed total {total}/{exp}." + ("" if total == exp else f"  ⚠ EXPECTED {exp} — investigate!"))

R4_DRIVER_EOF_7f3a
